import {createSyncUI} from './sync-ui.js';
import {analyze,propertyYear,household,validateState,RULES} from './engine.js';
import {initialState,newProperty,uid,upgradeScenario} from './data.js';
import {regularPayroll2026,payrollComparison} from './payroll.js';
import {effectiveState,STRATEGIES,strategyOn,propertyOn,scenarioPayroll} from './scenario.js';
import {buildHandoff} from './risk.js';
import {renderStrategies,renderRisk} from './planning-ui.js';
import {ScenarioStore,STORAGE_KEY,serializeScenario,deserializeScenario,MAX_BACKUP_BYTES} from './storage.js';
import {periodAmount,chartMarkup,chartDetail,cashNeeded} from './display.js';
const KEY=STORAGE_KEY;let state,loadError='',initiallyPersisted=false;try{const raw=localStorage.getItem(KEY);state=raw?deserializeScenario(raw):initialState();validateState(state);initiallyPersisted=!!raw;}catch(e){state=initialState();loadError='Saved data could not be read. Examples loaded; import a JSON backup to restore your scenario.';}
const persistence=new ScenarioStore({setItem:(k,v)=>localStorage.setItem(k,v)});persistence.persisted=initiallyPersisted;
let view='overview',selected=null,section='details',year=state.baseYear,dirty=false,deleted=null;
let period='monthly',visibleSeries={benefit:true,cash:true};try{const prefs=JSON.parse(localStorage.getItem('immoledger.view.v1'));if(prefs?.period==='yearly')period='yearly';}catch{}
let chartRows=[];
const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const euro=(v,d=0)=>new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR',maximumFractionDigits:d,minimumFractionDigits:d}).format(v||0);const percent=v=>`${Number(v||0).toFixed(1)}%`;const signed=v=>`${v>0?'+':''}${euro(v)}`;
const paths={home:'M3 10l9-7 9 7v11H3z M9 21v-8h6v8',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',building:'M5 21V3h14v18 M9 7h1 M14 7h1 M9 11h1 M14 11h1 M9 15h1 M14 15h1 M9 21v-3h6v3',chart:'M3 3v18h18 M6 15l5-5 4 3 6-8',tax:'M5 3h14v18l-3-2-4 2-4-2-3 2z M8 7h8 M8 11h8 M8 15h4',file:'M6 3h8l5 5v13H6z M14 3v6h5 M9 13h7 M9 17h7',book:'M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3z M12 6v16',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M13 6l6 6-6 6',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',up:'M6 14l6-6 6 6',down:'M6 10l6 6 6-6',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',wallet:'M3 5h17v15H3z M15 10h7v6h-7z',leaf:'M20 3C8 2 2 8 5 16s15 5 15-13z M5 21L16 8',check:'M4 12l5 5L20 6',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',clock:'M12 7v5l4 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.home}"/></svg>`;
const button=(text,action,cls='',attrs='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const notice=(text,warn=false)=>`<div class="notice ${warn?'warning':''}">${icon('info')}<span>${text}</span></div>`;
const field=(name,label,value,type='number',help='',opts={})=>`<div class="field ${opts.wide?'wide':''}"><label for="f-${esc(name)}">${label}</label>${type==='select'?`<select id="f-${esc(name)}" name="${esc(name)}">${opts.options.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select>`:type==='textarea'?`<textarea id="f-${esc(name)}" name="${esc(name)}" rows="2" maxlength="2000">${esc(value)}</textarea>`:`<input id="f-${esc(name)}" name="${esc(name)}" type="${type}" ${type==='number'?`min="${opts.min??0}" max="${opts.max??1000000000}" step="${opts.step??'any'}" ${opts.nullable?'':'required'}`:type==='text'?'required maxlength="250"':type==='month'?'required min="1950-01" max="2150-12"':''} value="${esc(value)}" ${opts.nullable?'data-nullable="true" placeholder="Automatic"':''}>`}${help?`<small>${help}</small>`:''}</div>`;
const check=(name,label,value)=>`<label class="field check"><input name="${name}" type="checkbox" ${value?'checked':''}>${label}</label>`;
const stat=(label,value,sub,ico,accent=false)=>`<div class="stat ${accent?'accent':''}"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon(ico)}</span></div><div class="stat-value">${value}</div><div class="stat-sub">${sub}</div></div>`;
const empty=text=>`<div class="empty">${text}</div>`;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function save(){validateState(state);const ok=persistence.save(state);dirty=!ok;syncUI.changed();if(!ok)toast('Browser storage unavailable. Export a JSON backup to keep your changes.');return ok;}
function header(title,sub,actions=''){return `<div class="page-head"><div><div class="eyebrow">Property & tax studio</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="actions">${actions}</div></div>`;}
function chart(rows){chartRows=rows;return chartMarkup(rows,{period,year,visible:visibleSeries});}
const perMoney=(v,d=0)=>euro(periodAmount(v,period),d);
const perSigned=v=>`${v>0?'+':''}${perMoney(v)}`;
const unit=()=>period==='monthly'?'Monthly average':'Annual';
const suffix=()=>period==='monthly'?'month avg.':'year';
function periodToolbar(a){return `<div class="display-toolbar no-print"><div class="period-choice"><span>Display amounts</span><div class="segmented" role="group" aria-label="Display period">${['monthly','yearly'].map(v=>`<button data-action="set-period" data-period="${v}" aria-pressed="${period===v}">${v==='monthly'?'Monthly':'Yearly'}</button>`).join('')}</div></div><button class="tax-rate-banner" data-action="show-tax"><span>Your marginal tax rate · ${year}<strong>${percent(a.final.marginal)}</strong></span><small>Before properties ${percent(a.pensions.marginal)} <span aria-hidden="true">→</span> after properties ${percent(a.final.marginal)} &nbsp; View steps ↗</small></button></div><p class="display-explainer no-print">${view==='report'?'Tax worksheets stay annual for tax review. ':''}${period==='monthly'?'Monthly averages = annual totals ÷ 12; individual months may differ.':'Flows are annual totals.'} Debt balances, purchase prices, tax rates and input units keep their own labels.</p>`;}
function payrollBanner(a){const p=state.payroll;if(!p||!strategyOn(state,'payrollAllowance')||!a.stages.some(v=>v.id===p.approvedPropertyId))return '';const c=payrollComparison(p,a.stages);return `<div class="payroll-banner"><div><span class="eyebrow">Historical payslip reference · ${esc(p.month)}</span><strong>${euro(c.approved.wageTax,2)} wage tax / month · ${euro(c.approved.payout,2)} bank payout</strong><p>Approved Freibetrag ${euro(p.annualAllowance)} / year; monthly payroll relief ${euro(c.relief,2)}. Property figures below remain formula-based estimates.</p></div>${button('See reconciliation '+icon('arrow'),'show-payroll','primary')}</div>`;}
function payrollView(a){const p=state.payroll,c={...payrollComparison(p,a.stages),proposed:scenarioPayroll(state,a.stages)},r=c.approved,base=a.stages.find(s=>s.id===c.baseId),match=Math.abs(r.payout-p.observedPayout)<.011&&Math.abs(r.wageTax-p.observedWageTax)<.011&&Math.abs(r.netBeforeAdjustments-p.observedNet)<.011;const variance=r.payout-p.observedPayout;const loanDiff=p.observedLoanPayment-p.observedLoanInterest-p.observedLoanPrincipal;return header('Reconcile with your payslip.','Your observed payroll, the approved Freibetrag and the property model, shown separately.',button('View household assessment','show-tax'))+`<div class="stats">${stat('Monthly wage tax',euro(r.wageTax,2),`Payslip: ${euro(p.observedWageTax,2)} · ${match?'matched to the cent':'check the difference'}`,'tax')}${stat('Bank payout / month',euro(r.payout,2),`Payslip: ${euro(p.observedPayout,2)} · variance ${euro(variance,2)}`,'wallet',true)}${stat('Current payroll tax relief',euro(c.relief,2),'Without allowance minus current wage tax · per month','leaf')}${stat('Approved annual Freibetrag',euro(p.annualAllowance),`${euro(r.monthlyAllowance,2)} applied each payroll month`,'file')}</div>${notice('The payslip records the total ELStAM Freibetrag. It does not itemize the rental-loss calculation or establish the final annual assessed loss. The property attribution below is your input; confirm it against the approved calculation. It is not added on top of property deductions in the annual assessment.')}<div class="split"><div class="card"><div class="card-head"><div><h2>Payroll bridge · ${esc(p.month)}</h2><p>Regular monthly salary · class ${esc(p.taxClass)} · 2026 payroll parameters</p></div><span class="badge ${match?'actual':''}">${match?'MATCHED':'REVIEW INPUTS'}</span></div>${[['Taxable salary',p.grossMonthly],['Tax-free jobticket / benefits',p.taxFreeMonthly],['Employee health (KV)',-r.health],['Employee pension (RV)',-r.pension],['Employee unemployment (AV)',-r.unemployment],['Employee care (PV)',-r.care],['Wage tax',-r.wageTax],['Solidarity + church',-r.soli-r.church]].map(([k,v])=>`<div class="break-row"><span>${k}</span><strong>${v<0?'− ':''}${euro(Math.abs(v),2)}</strong></div>`).join('')}<div class="break-row"><span>Net before ticket deductions · payslip ${euro(p.observedNet,2)}</span><strong>${euro(r.netBeforeAdjustments,2)}</strong></div><div class="break-row"><span>Net ticket / other deductions</span><strong>− ${euro(p.netDeductionsMonthly,2)}</strong></div><div class="break-row final"><span>Bank payout</span><strong>${euro(r.payout,2)}</strong></div><p class="small-text">Tax-free benefits and net deductions use the separate amounts entered below. Observed social payments can be used directly, without replacing them with a standard percentage.</p></div><div class="card"><h2>Why ${euro(r.wageTax,2)} is correct here</h2><div class="break-row"><span>Annual recorded Freibetrag</span><strong>${euro(p.annualAllowance,2)}</strong></div><div class="break-row"><span>Annual ÷ 12</span><strong>${euro(p.annualAllowance/12,2)}</strong></div><div class="break-row"><span>Applied monthly amount</span><strong>${euro(r.monthlyAllowance,2)}</strong></div><p class="small-text">The monthly allowance is rounded up to a full euro. An explicitly entered monthly amount takes precedence for the observed month.</p><div class="break-row"><span>Wage tax with no Freibetrag</span><strong>${euro(c.without.wageTax,2)} / mo</strong></div><div class="break-row"><span>Current wage tax</span><strong>${euro(r.wageTax,2)} / mo</strong></div><div class="break-row final"><span>Monthly payroll relief</span><strong>${euro(c.relief,2)}</strong></div><p class="small-text">Regular pay only, no bonuses, pensioner exemptions or factor method. The PAP uses a payroll Vorsorgepauschale; it is distinct from insurance deductions in the annual tax return.</p><a class="source-link" target="_blank" rel="noreferrer" href="https://www.bundesfinanzministerium.de/Content/DE/Downloads/Steuern/Steuerarten/Lohnsteuer/Programmablaufplan/2025-11-12-PAP-2026.html">BMF · official 2026 payroll plan ↗</a></div></div><div class="section-head"><h2>Property model vs payroll allowance</h2><span class="tag">${a.year} property model / ${esc(p.month)} payroll reference</span></div><div class="card">${base?`<div class="break-row"><span>${esc(base.name)}: modeled receipts − interest − costs − AfA</span><strong>${euro(base.result,2)} / year</strong></div><div class="break-row"><span>Payroll Freibetrag attributed to it by you</span><strong>− ${euro(p.annualAllowance,2)} / year</strong></div><div class="break-row"><span>Unreconciled difference in loss magnitude</span><strong>${euro(p.annualAllowance+base.result,2)}</strong></div><p class="small-text">Model: ${euro(base.income,2)} income − ${euro(base.interest,2)} interest − ${euro(base.deductibleCosts,2)} running costs − ${euro(base.afa,2)} AfA = ${euro(base.result,2)}. These assumptions are not back-solved to manufacture the approved amount.</p>`:empty('Choose which property the current payroll allowance relates to below.')}<p class="small-text">The difference needs the approved Lohnsteuerermäßigung calculation and confirmed rent, transfer date, building allocation and expense records. A useful-life appraisal alone does not establish the building’s tax basis. Enter any adviser-confirmed remaining useful life and accepted tax basis in the property profile.</p>${notice('Use the executed loan contract for nominal interest and scheduled payment; effective APR is a separate measure. An offer is not proof that the executed contract is unchanged. The reported bank payment split is shown below as an observation, not multiplied by 12 and presented as actual annual interest.',true)}</div><div class="section-head"><h2>Historical pay and the enabled scenario</h2></div><div class="card table-card"><div class="table-wrap"><table><thead><tr><th>Monthly payroll scenario</th><th>Wage tax</th><th>Bank payout</th><th>Change vs current</th></tr></thead><tbody><tr><td>No approved allowance · counterfactual</td><td>${euro(c.without.wageTax,2)}</td><td>${euro(c.without.payout,2)}</td><td>${euro(c.without.payout-r.payout,2)}</td></tr><tr><td>Current approved allowance · reference month</td><td>${euro(r.wageTax,2)}</td><td>${euro(r.payout,2)}</td><td>${euro(0,2)}</td></tr><tr><td>Enabled properties / payroll strategy · hypothetical approval</td><td>${euro(c.proposed.wageTax,2)}</td><td>${euro(c.proposed.payout,2)}</td><td>${euro(c.proposed.payout-r.payout,2)}</td></tr></tbody></table></div><div class="table-footer"><span>The scenario row uses enabled properties and the payroll-allowance switch only. Historical rows reproduce the document. The new allowance is unapproved. Salary and social costs held at the reference month.</span></div></div><div class="section-head"><h2>Your reported bank payment</h2><span class="tag">Month not independently confirmed</span></div><div class="stats">${stat('Monthly instalment',euro(p.observedLoanPayment,2),'User-reported bank payment','wallet')}${stat('Interest · Zinsen',euro(p.observedLoanInterest,2),'Potential rental deduction for the payment period','tax')}${stat('Principal · Tilgung',euro(p.observedLoanPrincipal,2),'Equity repayment; no income-tax deduction','building')}${stat('Split check',euro(loanDiff,2),'Payment minus interest minus principal · should be zero','check')}</div><form id="payroll-form">${sectionCard('Editable payroll reference','These inputs reproduce a regular monthly payslip. They do not override final annual tax.',`<div class="form-grid">${field('month','Reference payslip month',p.month,'month')}${field('taxClass','Payroll class',p.taxClass,'select','Supported regular-pay branch only.',{options:[['I','I'],['III','III'],['IV','IV · no factor']]})}${field('grossMonthly','Taxable gross salary · € / month',p.grossMonthly)}${field('annualAllowance','Recorded annual Freibetrag · €',p.annualAllowance)}${field('monthlyAllowance','Applied monthly Freibetrag · €',p.monthlyAllowance,'number','Blank = annual ÷ 12, rounded up to a whole euro.',{nullable:true})}${field('healthExtra','Insurer Zusatzbeitrag · total %',p.healthExtra,'number','TK reference: 17.29% total − 14.60% = 2.69%.',{max:10})}${field('approvedPropertyId','Property you attribute the existing allowance to',p.approvedPropertyId||'','select','Independent of property attribution order.',{options:[['','No property selected'],...state.properties.map(v=>[v.id,v.name])]})}${field('churchRate','Church tax rate · %',p.churchRate,'select','',{options:[[0,'None'],[8,'8%'],[9,'9%']]})}${field('taxFreeMonthly','Tax-free benefits · € / month',p.taxFreeMonthly)}${field('netDeductionsMonthly','Post-tax deductions · € / month',p.netDeductionsMonthly)}${field('health','Observed employee KV · € / month',p.health)}${field('pension','Observed employee RV · € / month',p.pension)}${field('unemployment','Observed employee AV · € / month',p.unemployment)}${field('care','Observed employee PV · € / month',p.care)}${field('observedWageTax','Observed wage tax · € / month',p.observedWageTax)}${field('observedNet','Observed net before deductions · € / month',p.observedNet)}${field('observedPayout','Observed bank payout · € / month',p.observedPayout)}${field('observedLoanPayment','Observed mortgage payment · €',p.observedLoanPayment)}${field('observedLoanInterest','Observed interest component · €',p.observedLoanInterest)}${field('observedLoanPrincipal','Observed principal component · €',p.observedLoanPrincipal)}</div><div class="toggle-row" style="margin-top:18px">${check('useObservedSocial','Use observed social payments',p.useObservedSocial)}${check('childless','Childless care surcharge',p.childless)}${check('saxony','Employed in Saxony',p.saxony)}</div>`)}<div class="save-bar"><small>Payroll comparison and annual assessment remain separate.</small><button class="btn primary" type="submit">${icon('check')} Save & reconcile</button></div></form>${notice('This payroll branch uses 2026 regular monthly pay rules for classes I/III/IV, statutory employee insurance and no pensioner exemptions, bonuses, factor or child allowance for surcharge calculation. Other circumstances require the official payroll calculation. Spouse income and pensions affect final annual assessment and are handled in Household tax.',true)}`;}

function cashSupport(a){return `<div class="card cash-support"><div class="card-head"><div><h2>Cash to fund without tax relief</h2><p>${year} · enabled properties only · ${suffix()}</p></div>${icon('wallet')}</div><div class="cash-support-values"><div><small>Cash needed before tax relief</small><strong>${perMoney(cashNeeded(a.cash),2)}</strong></div><div><small>Estimated property tax benefit</small><strong>${perMoney(a.totalBenefit,2)}</strong></div><div><small>Cash needed after tax relief</small><strong>${perMoney(cashNeeded(a.afterTaxCash),2)}</strong></div></div><p class="small-text">Before-tax need = max(0, full loan payments + entered cash costs − rental receipts). Includes principal, reserves and enabled confirmed guarantee premiums; AfA is not a cash payment. Tax relief is excluded entirely from the first figure. Portfolio surpluses offset other enabled properties’ shortfalls; a net surplus means €0 needed. ${a.cash>0?`Before-tax surplus: ${perMoney(a.cash,2)} / ${suffix()}. `:''}Rental income follows your entered collection assumptions; a guarantee is not assumed beyond confirmed terms. This is property funding only, not total household spending or a prediction of unemployment benefits. Monthly values are annual averages; rebate timing may require funding the before-tax amount first.</p></div>`;}
function dashboard(a,rows){const income=a.stages.reduce((s,p)=>s+p.income,0),interest=a.stages.reduce((s,p)=>s+p.interest,0),afa=a.stages.reduce((s,p)=>s+p.afa,0),costs=a.stages.reduce((s,p)=>s+p.deductibleCosts,0);return header('Your portfolio, in perspective.','A clear view of your properties, cash flow and the tax behind them.',button(`${icon('download')} Tax worksheet`,'report')+button(`${icon('plus')} Add property`,'add-property','primary'))+payrollBanner(a)+`<div class="stats">${stat(unit()+' rental receipts',perMoney(income),`${a.stages.length} active properties · includes tenant service charges`,'building')}${stat(unit()+' rental result',perSigned(a.totalResult),a.totalResult<0?'Rental loss available to offset income':'Positive rental income increases taxable income','tax')}${stat(unit()+' tax benefit',perMoney(a.totalBenefit),`${euro(a.totalBenefit)} / year · ${euro(a.totalBenefit/12)} / month average`,'leaf',true)}${stat(unit()+' cash after tax',perSigned(a.afterTaxCash),`${signed(a.afterTaxCash)} per year · after loan repayments`,'wallet')}</div>${cashSupport(a)}<div class="split"><div class="card"><div class="card-head"><div><h2>The next ten years</h2><p>${unit()} property tax benefit and after-tax cash flow</p></div><span class="tag">${state.baseYear} — ${state.baseYear+9}</span></div>${chart(rows)}<div class="legend"><span><i style="background:#608348"></i>Property tax benefit</span><span><i style="background:#93afae"></i>After-tax cash flow</span><span style="margin-left:auto">EUR / ${suffix()}</span></div></div><div class="card"><div class="card-head"><div><h2>Behind the rental result</h2><p>${year} · ${suffix()} · combined calculation</p></div>${icon('tax')}</div><div class="break-row"><span>Rental receipts</span><strong>${perMoney(income)}</strong></div><div class="break-row"><span>Loan interest</span><strong>− ${perMoney(interest)}</strong></div><div class="break-row"><span>Deductible running costs</span><strong>− ${perMoney(costs)}</strong></div><div class="break-row"><span>Building depreciation · AfA</span><strong>− ${perMoney(afa)}</strong></div><div class="break-row final"><span>Taxable result</span><strong>${perSigned(a.totalResult)}</strong></div><div class="bar-track"><span style="width:57%;background:#668850"></span><span style="width:30%;background:#bdd09f"></span><span style="width:13%;background:#dce5ca"></span></div><p class="small-text">Principal builds equity. It does not reduce taxable rental income.</p></div></div><div class="section-head"><h2>Your properties <span class="tag">${a.stages.length} active profiles</span></h2>${button('Manage properties '+icon('arrow'),'properties','small')}</div>${portfolioTable(a)}<div class="insight"><div class="bulb">${icon('leaf')}</div><div><strong>One portfolio. Two different results.</strong><p>Your properties repay ${euro(a.principal)} of debt this year. Cash flow includes those repayments; your taxable result includes AfA instead.</p></div></div>${notice('Planning estimate · Illustrative starting data. Confirm dates, rent, building allocation and custom AfA before using a worksheet. '+(year!==2026?'Future tax and social calculations reuse 2026 parameters.':''))}`;}
function portfolioTable(a){return `<div class="card table-card"><div class="table-wrap"><table><thead><tr><th>Property</th><th>Receipts / ${suffix()}</th><th>Result / ${suffix()}</th><th>Cash needed before tax / ${suffix()}</th><th>Tax benefit / ${suffix()}¹</th><th>Cash after tax / ${suffix()}²</th><th>Marginal tax after</th><th></th></tr></thead><tbody>${a.stages.map((p,i)=>`<tr><td><button class="link-button property-name" data-action="open-property" data-id="${esc(p.id)}"><span class="property-mark ${i%2?'blue':''}">${icon('building')}</span><span>${esc(p.name)}<small>${esc(state.properties.find(v=>v.id===p.id).location)}</small></span></button></td><td>${perMoney(p.income)}</td><td class="${p.result<0?'negative':'positive'}">${perSigned(p.result)}</td><td>${perMoney(cashNeeded(p.cash),2)}</td><td class="positive">${perSigned(p.saving)}</td><td class="${p.afterTaxCash<0?'negative':'positive'}">${perSigned(p.afterTaxCash)}</td><td><strong>${percent(p.marginal)}</strong></td><td><button class="btn icon-only" data-action="open-property" data-id="${esc(p.id)}" aria-label="Edit ${esc(p.name)}">${icon('arrow')}</button></td></tr>`).join('')||'<tr><td colspan="8">No properties yet. Add your first profile to begin.</td></tr>'}</tbody></table></div><div class="table-footer"><span>Cash needed is a positive funding gap; €0 means no gap. ¹ Attributed in portfolio order &nbsp; ² Signed cash flow after attributed tax benefit</span><span>Interest and AfA calculated separately</span></div></div>`;}
function properties(a){return header('A home for every property.','Keep each property’s financing, income and costs in its own profile.',button('Enable / disable profiles','show-scenarios')+button(icon('plus')+' Add property','add-property','primary'))+`<div class="profile-list">${a.stages.map((p,i)=>{const full=state.properties.find(v=>v.id===p.id);return `<div class="card profile-card"><div class="card-head"><div class="property-name"><span class="property-mark ${i%2?'blue':''}">${icon('building')}</span><span>${esc(p.name)}<small>${esc(full.location)}</small></span></div><span class="tag">${full.loans.length} loans</span></div><div class="profile-numbers"><div><small>Purchase price</small><strong>${euro(full.purchasePrice)}</strong></div><div><small>Rental result / ${suffix()} · ${year}</small><strong class="negative">${perSigned(p.result)}</strong></div><div><small>Cash needed before tax / ${suffix()}</small><strong>${perMoney(cashNeeded(p.cash),2)}</strong></div><div><small>Tax benefit / ${suffix()}</small><strong>${perMoney(p.saving)}</strong></div><div><small>Cash after tax / ${suffix()}</small><strong>${perSigned(p.afterTaxCash)}</strong></div></div><p class="small-text">${esc(full.afaEvidence||'No AfA evidence recorded')}</p><div class="actions">${button('Edit profile '+icon('arrow'),'open-property','primary',`data-id="${esc(p.id)}"`)}${button('Duplicate','duplicate','',`data-id="${esc(p.id)}"`)}${button(icon('trash'),'delete-property','danger',`data-id="${esc(p.id)}" aria-label="Delete ${esc(p.name)}"`)}</div></div>`;}).join('')||empty('Add a property to build your portfolio.')}</div>${deleted?notice('Property removed. '+button('Undo removal','undo-delete','small')):''}`;}
const sectionCard=(title,sub,body,action='')=>`<div class="card form-section"><div class="card-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>${body}</div>`;
function propertyEditor(){const p=state.properties.find(p=>p.id===selected);if(!p){view='properties';return properties(analyze(state,year));}const preview=effectiveState({...state,properties:[{...p,enabled:true}]}).properties[0];const r=propertyYear(preview,year);let body='';if(section==='details'){body=sectionCard('Property & purchase','Amounts below describe the whole property. Ownership is applied to all calculations.',`<div class="form-grid">${field('name','Profile name',p.name,'text')}${field('location','Location / reference',p.location,'text')}${field('start','Rental / AfA start month',p.start,'month','Month-granular model; adjust actuals for exact transfer dates.')}${field('purchasePrice','Purchase price · €',p.purchasePrice)}${field('buyerCosts','Buyer-paid capitalizable acquisition costs · €',p.buyerCosts,'number','Zero if you pay none. Allocation to the building is applied below.')}${field('equity','Initial own cash invested · €',p.equity||0,'number','For your acquisition funding check; not a tax deduction.')}${field('ownership','Your tax-assessed ownership · %',p.ownership,'number','Use 100% for a jointly assessed household owning all of it.',{max:100})}</div>`)+sectionCard('Building depreciation','Land cannot be depreciated. A higher custom rate requires supporting evidence.',`<div class="form-grid">${field('buildingShare','Building share of acquisition basis · %',p.buildingShare,'number','A value allocation, not a floor-area ratio.',{max:100})}${field('afaRate','Annual AfA rate · %',p.afaRate,'number','Standard: 2.5% before 1925; 2% 1925–2022; 3% from 2023.',{max:100})}${field('afaBasis','Override building basis · €',p.afaBasis,'number','Optional adviser-confirmed total building basis before ownership.',{nullable:true})}${field('afaEvidence','Allocation / AfA evidence and assumptions',p.afaEvidence,'textarea','Record appraisal, agreement, completion year and document reference.',{wide:true})}</div>`)+notice(`Current building basis: <strong>${euro(r.basis)}</strong> after ownership. Acquisition costs are capitalized. Operating costs belong in the cost schedule.`);body+=sectionCard('Confirm the assumptions you checked','Only confirmed active-property inputs can support a resilience score.',`<div class="form-grid two">${check('confirmations.rent','Rent and parking receipts verified',p.confirmations.rent)}${check('confirmations.buildingShare','Building basis and AfA reviewed',p.confirmations.buildingShare)}${check('confirmations.dates','Rental and loan dates verified',p.confirmations.dates)}${check('confirmations.loans','Executed loan terms verified',p.confirmations.loans)}${check('confirmations.costs','Owner costs / fee waivers verified',p.confirmations.costs)}${check('confirmations.growth','Rent-step assumption explicitly chosen',p.confirmations.growth)}</div><p class="small-text">Checking a box records your confirmation; it does not validate documents or establish Finanzamt acceptance. Future rent and market outcomes remain uncertain.</p>`);
}else if(section==='income'){body=sectionCard('Rent & reimbursements','Cold rent increases at the configured interval, starting from the rental start month.',`<div class="form-grid">${field('rent',(p.rentIncludesParking?'Combined cold + parking rent · € / month':'Cold rent · € / month'),p.rent)}${field('parking','Additional parking rent · € / month',p.parking,'number',p.rentIncludesParking?'Already included in combined rent above; keep0 until split is entered.':'Held constant in projections.')}${field('serviceIncome','Tenant service-charge receipts · € / month',p.serviceIncome,'number','Include reimbursements and add the corresponding paid expenses as costs.')}${check('rentIncludesParking','Rent above already includes parking (keep additional parking at0)',p.rentIncludesParking)}${field('rentGrowth','Rent increase at each step · %',p.rentGrowth,'number','Scenario assumption, subject to legal and contractual limits.',{max:100})}${field('rentEvery','Years between increases',p.rentEvery,'number','First increase after this many years.',{min:1,max:100,step:1})}${field('vacancy','Expected uncollected / vacant rent · %',p.vacancy,'number','Applies to cold rent, parking and service receipts.',{max:100})}</div>`)+notice('Rent increases are planning assumptions. Actual permissible increases depend on the lease, local Mietspiegel and applicable limits. This app does not validate a rent-increase notice.');}else if(section==='loans'){body=sectionCard('Every loan, one clear picture','Use nominal interest (Sollzins), not effective APR. Enter a contract instalment to override the derived annuity payment.',p.loans.map((l,i)=>`<div class="entry"><div class="entry-head"><h3>Loan ${i+1}</h3>${button('Remove loan','remove-loan','danger small',`data-index="${i}"`)}</div><div class="form-grid">${field(`loans.${i}.name`,'Loan name',l.name,'text')}${field(`loans.${i}.amount`,'Original disbursed principal · €',l.amount)}${field(`loans.${i}.start`,'First payment month',l.start,'month')}${field(`loans.${i}.interest`,'Nominal interest · %',l.interest,'number','Annual rate; monthly accrual.',{max:100})}${field(`loans.${i}.monthlyPayment`,'Contract monthly instalment · €',l.monthlyPayment,'number','Optional. Overrides the payment derived from initial Tilgung.',{nullable:true})}${field(`loans.${i}.firstInterest`,'First instalment interest · €',l.firstInterest,'number','Optional bank-confirmed interest for a short first payment period.',{nullable:true})}${field(`loans.${i}.repayment`,'Initial Tilgung · %',l.repayment,'number','Payment stays constant; principal share increases.',{max:100})}${field(`loans.${i}.fixedYears`,'Interest fixation · years',l.fixedYears,'number','Forecast retains the rate after expiry and flags it.',{min:1,max:100,step:1})}${field(`loans.${i}.fixedUntil`,'Fixed rate through month',l.fixedUntil||'','month','Optional exact expiry; blank uses the fixation years.').replace('type="month" required','type="month"')}${field(`loans.${i}.extra`,'Extra repayment every December · €',l.extra,'number','Check your contract’s Sondertilgung allowance.')}</div><p class="small-text">${year}: ${euro(r.loans[i].interest)} interest · ${euro(r.loans[i].principal)} principal · ${euro(r.loans[i].balance)} outstanding (whole loan).</p></div>`).join('')||empty('No financing entered. Add as many separate loans as you need.'),button(icon('plus')+' Add loan','add-loan','small'))+notice(`Funding check: purchase + buyer costs ${euro(p.purchasePrice+p.buyerCosts)}; loans + own cash ${euro(p.loans.reduce((s,l)=>s+l.amount,0)+(p.equity||0))}. These are acquisition inputs, not a claim that all financing has been drawn. Zero-interest loans use the Tilgung percentage to define their payment.`);}else if(section==='costs'){body=sectionCard('Costs, with a start and an end','SEV, WEG administration, repairs, building insurance, rent guarantee or other expenses.',p.costs.map((c,i)=>`<div class="entry"><div class="entry-head"><h3>Cost ${i+1} ${c.enabled===false?'<span class="badge">Disabled</span>':''}</h3><div class="actions">${button(c.enabled===false?'Enable cost':'Disable cost','toggle-cost','small',`data-index="${i}"`)}${button('Remove cost','remove-cost','danger small',`data-index="${i}"`)}</div></div><div class="form-grid">${field(`costs.${i}.name`,'Description',c.name,'text')}${field(`costs.${i}.amount`,'Payment amount · €',c.amount)}${field(`costs.${i}.frequency`,'Payment frequency',c.frequency,'select','',{options:[['monthly','Monthly'],['annual','Annually in start month'],['once','One-off in start month']]})}${field(`costs.${i}.from`,'First payment month',c.from,'month')}${field(`costs.${i}.to`,'Last payment month',c.to,'month','Blank means ongoing.') .replace('type="month" required','type="month"')}${field(`costs.${i}.type`,'Tax treatment',c.type,'select','',{options:[['deductible','Deductible running cost'],['reserve','Reserve contribution · cash only'],['capital','Capital expenditure · review AfA'],['private','Non-deductible expense']]})}${field(`costs.${i}.growth`,'Annual cost increase · %',c.growth,'number','Each anniversary of the start month.',{max:100})}</div></div>`).join('')||empty('No costs entered. Add fees and payments, including future ones.'),button(icon('plus')+' Add cost','add-cost','small'))+notice('Do not deduct the full Hausgeld and then enter its components again. Split it into paid deductible expenses, reserve contributions and private/non-deductible items. Reserve spending may become deductible when the WEG actually uses it; avoid counting that spending twice.',true);}else if(section==='guarantee'){const g=p.guaranteePlan;body=sectionCard('Future vacancy-rent guarantee','Desired2029–2036 coverage. Premium and coverage are unknown until you enter the quote.',`<div class="form-grid">${field('guaranteePlan.startYear','Coverage start year',g.startYear,'number','',{min:2026,max:2150,step:1})}${field('guaranteePlan.endYear','Coverage end year · inclusive',g.endYear,'number','',{min:2026,max:2150,step:1})}${field('guaranteePlan.annualPremium','Annual premium · €',g.annualPremium,'number','Enter a quoted amount; blank is unpriced, not free.',{nullable:true})}${field('guaranteePlan.coveragePercent','Vacancy lost-rent coverage · %',g.coveragePercent,'number','Only cold/parking rent; no assumed reimbursement of service charges.',{nullable:true,max:100})}</div><div class="toggle-row">${check('guaranteePlan.enabled','Enable this guarantee plan',g.enabled)}${check('guaranteePlan.confirmed','I verified premium, covered rent, dates and exclusions',g.confirmed)}</div><p class="small-text">You report existing seller guarantees until2029. Their precise end date, waiting periods, payment limits and counterparty terms have not been established here, so no current guarantee credit is assumed. This new plan adds its annual premium as a deductible planning cost and mitigates only the eligible-year vacancy stress once fully confirmed. Counterparty failure and exclusions remain outside the model.</p>`);}else{const act=p.actuals[year]||{};body=sectionCard(`Actual-year overrides · ${year}`,'Blank uses the forecast. Zero is a real override. Enter YOUR ownership share, not the whole property.',`<div class="form-grid">${field(`actuals.${year}.income`,'Total rental receipts · €',act.income,'number','Cold rent + parking + service receipts.',{nullable:true})}${field(`actuals.${year}.interest`,'Interest actually paid · €',act.interest,'number','Use lender annual certificates.',{nullable:true})}${field(`actuals.${year}.principal`,'Principal actually repaid · €',act.principal,'number','Cash flow only.',{nullable:true})}${field(`actuals.${year}.afa`,'Tax depreciation · €',act.afa,'number','Adviser-confirmed AfA.',{nullable:true})}${field(`actuals.${year}.deductibleCosts`,'Deductible expenses paid · €',act.deductibleCosts,'number','Excludes interest and AfA.',{nullable:true})}${field(`actuals.${year}.cashCosts`,'All cash costs paid · €',act.cashCosts,'number','Includes deductible costs and reserve/capital payments; excludes loan payments.',{nullable:true})}${field(`actuals.${year}.note`,'Evidence / document references',act.note,'textarea','Overrides replace the totals above. Loan balance remains a modeled balance.',{wide:true})}</div>`,button('Clear this year','clear-actuals','small'))+notice('Annual overrides do not retroactively rewrite the loan schedule or depreciation basis. Use the worksheets with supporting records; the app does not verify invoices or automatically classify acquisition-related repairs.');}
return header(esc(p.name),esc(p.location)+' · Edit the assumptions behind your calculation.',button('All properties','properties')+button('View worksheet','report'))+(!propertyOn(p)?notice('This saved property is disabled. The figures below preview this profile only; it contributes nothing to the portfolio, risk score or AI report.',true):'')+`<div class="stats">${stat(unit()+' rental result · '+year,perSigned(r.result),'Modeled letting result · separate from payroll Freibetrag','tax')}${stat(unit()+' cash needed before tax',perMoney(cashNeeded(r.cash),2),`Cash flow ${perSigned(r.cash)} · full loan payments and reserves`,'wallet')}${stat(unit()+' principal repaid',perMoney(r.principal),'Equity from amortization','building')}${stat('Outstanding debt',euro(r.balance),'Modeled balance at year end · not divided by 12','chart')}</div><div class="tabs">${[['details','Purchase & AfA'],['income','Rental income'],['loans','Loans'],['costs','Cost schedule'],['guarantee','Guarantee plan'],['actuals','Actual-year records']].map(([v,l])=>`<button class="tab ${section===v?'active':''}" data-action="section" data-section="${v}">${l}</button>`).join('')}</div><form id="profile-form">${body}<div class="save-bar"><small>Changes recalculate your entire portfolio when saved.</small><button class="btn primary" type="submit">${icon('check')} Save & recalculate</button></div></form>${r.warnings.length?notice(r.warnings.map(esc).join('<br>'),true):''}`;}
function projection(rows){const cumulative=rows.reduce((s,r)=>s+r.afterTaxCash,0),debtRepaid=rows.reduce((s,r)=>s+r.principal,0);return header('See beyond this year.','Ten calendar years, with monthly loan amortization and your scheduled rent and cost changes.',button(icon('download')+' Export '+(period==='monthly'?'monthly':'annual')+' CSV','export-projection'))+`<div class="stats">${stat('Ten-year tax benefit',euro(rows.reduce((s,r)=>s+r.totalBenefit,0)),'Combined property tax reduction','leaf',true)}${stat('Cumulative cash after tax',signed(cumulative),'Excludes initial own cash and property sale proceeds','wallet')}${stat('Principal repaid',euro(debtRepaid),'Debt reduction during this projection','building')}${stat('Debt at horizon',euro(rows.at(-1).balance),'Unchanged rates assumed beyond fixation','chart')}</div><div class="card"><div class="card-head"><div><h2>Your portfolio trajectory</h2><p>Change each property’s rent, financing and cost schedule to explore scenarios.</p></div><span class="tag">Frozen 2026 tax rules</span></div>${chart(rows)}<div class="legend"><span><i style="background:#608348"></i>Tax benefit</span><span><i style="background:#93afae"></i>After-tax cash</span></div></div><div class="section-head"><h2>${unit()} portfolio ledger</h2><span class="tag">EUR / ${suffix()}</span></div><p class="small-text">Cash needed before tax excludes all property tax relief and nets rental receipts against full loan payments and cash costs. €0 indicates no funding gap; monthly amounts are annual averages.</p><div class="card table-card"><div class="table-wrap"><table><thead><tr><th>Year</th><th>Receipts</th><th>Interest</th><th>AfA</th><th>Rental result</th><th>Cash needed before tax</th><th>Tax benefit</th><th>Cash after tax</th><th>Principal</th><th>Year-end debt</th><th>Marginal tax</th></tr></thead><tbody>${rows.map(r=>`<tr><td><button class="link-button" data-action="select-year" data-year="${r.year}">${r.year} ${r.year===year?'<span class="badge">Selected</span>':''}</button></td><td>${perMoney(r.stages.reduce((s,p)=>s+p.income,0))}</td><td>${perMoney(r.stages.reduce((s,p)=>s+p.interest,0))}</td><td>${perMoney(r.stages.reduce((s,p)=>s+p.afa,0))}</td><td class="${r.totalResult<0?'negative':'positive'}">${perSigned(r.totalResult)}</td><td>${perMoney(cashNeeded(r.cash),2)}</td><td>${perSigned(r.totalBenefit)}</td><td class="${r.afterTaxCash<0?'negative':'positive'}">${perSigned(r.afterTaxCash)}</td><td>${perMoney(r.principal)}</td><td>${euro(r.balance)}</td><td>${percent(r.final.marginal)}</td></tr>`).join('')}</tbody></table></div></div>${notice('These are scenarios, not predictions. The 2026 income-tax tariff, social caps and child parameters are reused throughout; only the new depot mechanism activates from 2027. Salary follows your growth input. No market appreciation or property sale is assumed. Loan rates remain unchanged after fixation.',true)}${[...new Set(rows.flatMap(r=>r.warnings))].length?`<details><summary>Review projection assumptions and flags</summary>${[...new Set(rows.flatMap(r=>r.warnings))].map(w=>`<p>${esc(w)}</p>`).join('')}</details>`:''}`;}
function taxView(a){const h=state.household,live=effectiveState(state).household;return header('Follow every euro of tax.','Your household, progressive tax rates and the incremental effect of each property.',button('Tax worksheet '+icon('arrow'),'report'))+`<div class="stats">${stat(unit()+' estimated tax',perMoney(a.final.tax),'Income tax + solidarity + approximate church tax','tax')}${stat('Marginal income-tax rate',percent(a.final.marginal),'On the next euro of taxable income · after all steps','chart')}${stat(unit()+' property tax benefit',perMoney(a.totalBenefit),'Final liability reduction, separate from refund','leaf',true)}${stat('Household available / '+suffix(),perMoney(a.householdAvailable),'After social, tax, pension deposits and property cash flow','wallet')}</div><div class="card"><div class="card-head"><div><h2>Your tax journey · ${year}</h2><p>Each saving is recalculated using the progressive tariff and favorable checks.</p></div><span class="tag">${h.joint?'Joint assessment · splitting':'One-person assessment'}</span></div><div class="waterfall"><div class="step"><span class="step-num">1</span><div class="step-name">Salary after standard deductions<small>${euro(a.baseline.gross)} gross − ${euro(a.baseline.deductibleSocial)} deductible social costs − employment / other deductions.<br>Taxable: ${euro(a.baseline.taxable)} · selected assessment already applies.</small></div><div class="step-amount">${perMoney(a.baseline.tax)}<small>tax / ${suffix()}</small></div><div class="step-rate">${percent(a.baseline.marginal)}<small>marginal income-tax rate</small></div></div><div class="step"><span class="step-num">2</span><div class="step-name">Tax class ${esc(h.taxClass)}<small>Changes wage withholding, not final annual liability. Joint splitting is determined by assessment, independently of class.</small></div><div class="step-amount">${euro(0)}<small>annual tax change</small></div><div class="step-rate">${percent(a.baseline.marginal)}<small>rate unchanged</small></div></div>${a.pensionStages.map((r,i)=>`<div class="step"><span class="step-num">${i+3}</span><div class="step-name">${esc(r.label)}<small>Own contribution: ${euro(r.monthly)} / month${r.key.includes('Depot')||r.key==='depotMonthly'?' · new depot support from 2027':''}.<br>Annual taxable base: ${euro(r.taxable)} · tax / ${suffix()}: ${perMoney(r.tax)}</small></div><div class="step-amount positive">${perSigned(r.saving)}<small>tax saved / ${suffix()}</small></div><div class="step-rate">${percent(r.marginal)}<small>marginal income-tax rate</small></div></div>`).join('')}${(strategyOn(state,'privateMonthly')||strategyOn(state,'spousePrivateMonthly'))?`<div class="step"><span class="step-num">7</span><div class="step-name">Ordinary private pension<small>Your ${euro(live.privateMonthly)} / month + spouse ${euro(h.joint?live.spousePrivateMonthly:0)} / month. Cash commitment with no current contribution deduction.<br>Total modeled depot allowance: ${euro(a.pensions.allowance)} credited to contracts; additional depot tax benefit: ${euro(a.pensions.depotExtraTaxBenefit)}.</small></div><div class="step-amount">${euro(0)}<small>current tax saved</small></div><div class="step-rate">${percent(a.pensions.marginal)}<small>rate unchanged</small></div></div>`:''}${a.stages.map((r,i)=>`<div class="step"><span class="step-num">${i+8}</span><div class="step-name">${esc(r.name)} <span class="inline-controls no-print">${i?button(icon('up'),'move-up','icon-only small',`data-id="${esc(r.id)}" aria-label="Move ${esc(r.name)} earlier"`):''}${i<a.stages.length-1?button(icon('down'),'move-down','icon-only small',`data-id="${esc(r.id)}" aria-label="Move ${esc(r.name)} later"`):''}</span><small>Rental result / ${suffix()}: ${perSigned(r.result)} · annual taxable base: ${euro(r.taxable)} · tax / ${suffix()}: ${perMoney(r.tax)}</small></div><div class="step-amount ${r.saving>=0?'positive':'negative'}">${perSigned(r.saving)}<small>benefit / ${suffix()}</small></div><div class="step-rate">${percent(r.marginal)}<small>marginal income-tax rate</small></div></div>`).join('')}</div><p class="small-text">Reordering allocates the progressive benefit differently. The combined annual tax stays the same. A marginal rate applies to the next euro; it is not a flat rate on all income.</p></div><div class="split" style="margin-top:22px"><div class="card"><h2>Household position / ${suffix()}</h2><div class="break-row"><span>Gross employment income</span><strong>${perMoney(a.final.gross)}</strong></div><div class="break-row"><span>Employee social contributions</span><strong>− ${perMoney(a.final.social)}</strong></div><div class="break-row"><span>Final tax / ${suffix()}</span><strong>− ${perMoney(a.final.tax)}</strong></div><div class="break-row"><span>Kindergeld + replacement benefits</span><strong>+ ${perMoney(a.final.kindergeld+h.progression)}</strong></div><div class="break-row"><span>Pension deposits · own contributions</span><strong>− ${perMoney(a.final.pensionCost)}</strong></div><div class="break-row"><span>Property cash flow before tax</span><strong>${perSigned(a.cash)}</strong></div><div class="break-row final"><span>Available after these commitments</span><strong>${perMoney(a.householdAvailable)} / ${suffix()}</strong></div><p class="small-text">Before living costs and other investments. Depot allowances stay in the contract and are excluded from spendable cash.</p></div><div class="card"><h2>Refund or payroll relief?</h2><p class="small-text">A tax benefit is not automatically the refund. Enter actual income tax, solidarity and church tax withheld or prepaid for this assessment.</p><div class="break-row"><span>Annual tax paid / withheld</span><strong>${euro(h.withheld+(h.joint?h.spouseWithheld:0))}</strong></div><div class="break-row"><span>Estimated annual final liability</span><strong>${euro(a.final.tax)}</strong></div><div class="break-row final"><span>${a.final.refund>=0?'Estimated refund':'Estimated balance due'}</span><strong>${euro(Math.abs(a.final.refund))}</strong></div><p class="small-text">${h.withheld+(h.joint?h.spouseWithheld:0)===0?'No withholding has been entered. The amount above assumes nothing was paid.':''} An approved Lohnsteuer-Freibetrag can bring some relief into payroll; this app does not calculate the BMF payroll PAP or submit an application.</p><a class="source-link" href="https://www.bmf-steuerrechner.de/" target="_blank" rel="noreferrer">Official BMF wage-tax calculator ↗</a></div></div><form id="household-form">${sectionCard('Household & employment','Full-year resident employees. Use annual amounts; spouse inputs apply only to joint assessment.',`<div class="form-grid">${field('gross','Your annual gross salary · €',h.gross)}${field('spouseGross','Spouse annual gross salary · €',h.spouseGross)}${field('salaryGrowth','Annual salary growth · %',h.salaryGrowth,'number','Applies after the scenario base year.',{max:100})}${field('taxClass','Payroll tax class combination',h.taxClass,'select','For context only; does not alter annual tax.',{options:[['III/V','III / V'],['IV/IV','IV / IV'],['IV factor','IV / IV with factor'],['I','I'],['II','II']]})}${field('children','Full-year children eligible for Kindergeld',h.children,'number','Model uses full child allowances for a joint household.',{max:20,step:1})}${field('childrenUnder25','Children under 25 for care contribution',h.childrenUnder25,'number','Care discounts for 2nd–5th child under 25.',{max:20,step:1})}${field('healthExtra','GKV insurer Zusatzbeitrag · total %',h.healthExtra,'number','Employee pays half. Default 2.9%; use your insurer’s rate.',{max:10})}${field('churchRate','Church tax rate · %',h.churchRate,'select','Approximate surcharge; circular deductibility and caps excluded.',{options:[[0,'No church tax'],[8,'8% · Bavaria / Baden-Württemberg'],[9,'9% · other states']]})}${field('progression','Net wage-replacement benefits · € / year',h.progression,'number','ALG I, Elterngeld etc. Simplified Progressionsvorbehalt; verify adjusted statutory amount.')}</div><div class="toggle-row" style="margin-top:18px">${check('joint','Joint assessment',h.joint)}${check('parent','Parent status (including adult children)',h.parent)}${check('saxony','Employed in Saxony',h.saxony)}</div>`)}${sectionCard('Pensions · each person separately','Own contributions in euros per month. New depot support starts in 2027.',`<div class="form-grid two"><div><h3>You</h3><div class="form-grid two">${field('depotMonthly','Altersvorsorgedepot · € / month',h.depotMonthly)}${field('depotChildren','Children allocated to your depot',h.depotChildren,'number','Assign each child once across both contracts.',{max:20,step:1})}${field('rurupMonthly','Certified Rürup · € / month',h.rurupMonthly)}${field('privateMonthly','Ordinary private pension · € / month',h.privateMonthly,'number','Schicht 3: no contribution deduction.')}</div>${check('depotEligible','Directly eligible for depot support',h.depotEligible)}</div><div><h3>Spouse</h3><div class="form-grid two">${field('spouseDepotMonthly','Altersvorsorgedepot · € / month',h.spouseDepotMonthly)}${field('spouseDepotChildren','Children allocated to spouse depot',h.spouseDepotChildren,'number','No child may be counted twice.',{max:20,step:1})}${field('spouseRurupMonthly','Certified Rürup · € / month',h.spouseRurupMonthly)}${field('spousePrivateMonthly','Ordinary private pension · € / month',h.spousePrivateMonthly)}</div>${check('spouseDepotEligible','Spouse directly eligible for depot support',h.spouseDepotEligible)}</div></div>${notice('Indirect spouse eligibility, legacy Riester, career-starter bonuses and mixed legacy/new contracts need an individual calculation. Leave eligibility off for unsupported contracts; a regular broker ETF account is not a certified Altersvorsorgedepot. 2026 contributions are treated as cash outflows only.')}`)}${sectionCard('Deductions & tax already paid','Automatic insurance deductions are estimates. Optional overrides should come from annual payroll certificates.',`<div class="form-grid">${field('otherDeductions','Other eligible special deductions · € / year',h.otherDeductions,'number','Replaces the €36 / person special-expense allowance if larger. Excludes modeled pensions / insurance.')}${field('socialOverride','Total employee social cash payments · € / year',h.socialOverride,'number','Household combined; blank = statutory estimate.',{nullable:true})}${field('deductibleOverride','Tax-deductible insurance contributions · € / year',h.deductibleOverride,'number','Combined employee deductible pension + basic health + care. Blank = automatic.',{nullable:true})}${field('withheld','Your tax withheld / prepaid · € / year',h.withheld)}${field('spouseWithheld','Spouse tax withheld / prepaid · € / year',h.spouseWithheld)}</div>`)}<div class="save-bar"><small>Recalculate tax, attribution and all ten forecast years.</small><button class="btn primary" type="submit">${icon('check')} Save household & recalculate</button></div></form>${notice('Standard employee estimates: pension 9.3%, unemployment 1.3%, health 7.3% + half insurer Zusatzbeitrag, care 1.8% plus childless surcharge (with regional / child adjustments). Capped at 2026 thresholds. Annual liability is an estimate; payroll and complex cases require the official calculation.',true)}${a.final.unclamped<0?notice('Taxable income falls below zero. This app floors current tax at zero and does not model loss carrybacks, carryforwards or loss-allocation restrictions.',true):''}`;}
function report(a){return header('A worksheet you can trace.','A combined summary with separate property schedules for your tax review.',button(icon('download')+' Export CSV','export-report')+button(icon('file')+' Print / Save PDF','print','primary'))+`<div class="report-head"><h1>Vermietung und Verpachtung · Berechnungsübersicht</h1><p>Tax year ${year} · Prepared ${new Date().toLocaleDateString('de-DE')} · ImmoLedger planning / review worksheet</p></div>${notice('Review worksheet — not an official Anlage V or an ELSTER submission. A forecast alone does not substantiate a tax claim. Check ownership, bank certificates, actual receipts, paid expenses and accepted AfA; retain supporting documents.',true)}<div class="stats">${stat('Rental receipts',euro(a.stages.reduce((s,p)=>s+p.income,0)),'Mieteinnahmen incl. reimbursements','building')}${stat('Taxable rental result',signed(a.totalResult),'Überschuss / Verlust · all properties','tax')}${stat('Estimated property tax benefit',euro(a.totalBenefit),'Household liability reduction','leaf',true)}${stat('Monthly relief equivalent',euro(a.totalBenefit/12),'Subject to approved payroll allowance / assessment','wallet')}</div>${a.stages.map((r,i)=>{const p=state.properties.find(v=>v.id===r.id);return `<div class="section-head"><h2>${esc(p.name)}</h2><span class="tag">${r.actual?'Actual overrides entered':'Forecast assumptions'} · ${year} · ${p.ownership}% share</span></div><div class="card table-card"><div class="table-wrap"><table><thead><tr><th>Item / Position</th><th>Annual amount · €</th><th>Tax treatment</th></tr></thead><tbody><tr><td>Rental receipts / Mieteinnahmen inkl. Umlagen</td><td>${euro(r.income,2)}</td><td>Income</td></tr><tr><td>Loan interest / Schuldzinsen</td><td>− ${euro(r.interest,2)}</td><td>Werbungskosten</td></tr><tr><td>Paid deductible expenses / laufende Werbungskosten</td><td>− ${euro(r.deductibleCosts,2)}</td><td>As classified / overridden</td></tr><tr><td>Building depreciation / Gebäude-AfA</td><td>− ${euro(r.afa,2)}</td><td>${p.afaRate}% · basis ${euro(r.basis,2)} after ownership</td></tr><tr><td><strong>Taxable result / Einkünfte aus Vermietung</strong></td><td><strong>${signed(r.result)}</strong></td><td>${r.result<0?'Verlust':'Überschuss'}</td></tr><tr><td>Principal repaid / Tilgung</td><td>${euro(r.principal,2)}</td><td>Cash only · not deductible</td></tr><tr><td>All operating / reserve / capital cash payments</td><td>${euro(r.costs,2)}</td><td>Cash only subtotal · do not deduct again</td></tr><tr><td>Cash flow before tax relief</td><td>${signed(r.cash)}</td><td>Income − interest − principal − cash costs</td></tr><tr><td>Cash needed before tax relief</td><td>${euro(cashNeeded(r.cash),2)}</td><td>Positive funding gap; no estimated rebate included</td></tr><tr><td>Attributed property tax benefit</td><td>${euro(r.saving,2)}</td><td>Depends on household assessment and portfolio order</td></tr><tr><td>Cash needed after tax relief</td><td>${euro(cashNeeded(r.afterTaxCash),2)}</td><td>After estimated attributed tax benefit</td></tr></tbody></table></div></div><details class="no-print" open><summary>Loan and cost detail · ${esc(p.name)}</summary><div class="table-wrap"><table><thead><tr><th>Loan · whole loan figures</th><th>Interest</th><th>Principal</th><th>Year-end balance</th></tr></thead><tbody>${r.loans.map(l=>`<tr><td>${esc(l.name)}</td><td>${euro(l.interest,2)}</td><td>${euro(l.principal,2)}</td><td>${euro(l.balance,2)}</td></tr>`).join('')}</tbody></table><table><thead><tr><th>Cost · ownership share</th><th>Cash amount</th><th>Classification</th></tr></thead><tbody>${r.costDetails.map(c=>`<tr><td>${esc(c.name)}</td><td>${euro(c.amount,2)}</td><td>${esc(c.type)}</td></tr>`).join('')}</tbody></table></div><p>Detail is forecast-based. Actual overrides replace annual totals, not these supporting modeled line items.</p></details><p class="small-text"><strong>Evidence:</strong> ${esc(p.afaEvidence||'None recorded')}${r.note?`<br><strong>${year} actual records:</strong> ${esc(r.note)}`:''}</p>${r.warnings.length?`<p class="report-warning">${r.warnings.map(esc).join(' • ')}</p>`:''}`;}).join('')}${cashSupport(a)}<div class="report-summary"><span>Combined taxable rental result / Gesamtergebnis · ${year}</span><span>${signed(a.totalResult)}</span></div><div class="card"><h2>Household tax estimate · ${year}</h2><div class="break-row"><span>Tax before properties (after pension optimization)</span><strong>${euro(a.pensions.tax)}</strong></div><div class="break-row"><span>Tax after all properties</span><strong>${euro(a.final.tax)}</strong></div><div class="break-row"><span>Final taxable income · zu versteuerndes Einkommen</span><strong>${euro(a.final.taxable)}</strong></div><div class="break-row"><span>Marginal income-tax rate after properties</span><strong>${percent(a.final.marginal)}</strong></div><div class="break-row final"><span>Estimated property tax benefit</span><strong>${euro(a.totalBenefit)}</strong></div></div><p class="small-text">Calculation basis: 2026 EStG §32a tariff and social parameters ${year>2026?'(held constant for this projected year)':''}. Joint assessment: ${state.household.joint?'yes':'no'}. Class ${esc(state.household.taxClass)} is context only. ${a.stages.some(r=>!r.actual)?'Includes forecast property records.':''} Reviewed sources: 06 November 2026. All values depend on the entered assumptions; this worksheet does not establish deductibility or entitlement to a refund.</p>`;}
function methodology(){return header('Know what’s behind the numbers.','Research, assumptions and the boundaries of this calculation.',button(icon('download')+' Save JSON','export-json'))+`<div class="method-grid">${sectionCard('01 · Taxable result ≠ cash flow','',`<p>Rental result = receipts − paid deductible interest − eligible operating costs − building AfA. Tilgung and transfers to a WEG maintenance reserve are excluded from deductions.</p><p>Cash flow = receipts − full loan payments − all cash costs. The attributed property tax benefit is added to derive after-tax cash flow. Purchase equity is not repeated as an annual expense.</p><a class="source-link" target="_blank" rel="noreferrer" href="https://www.elster.de/eportal/helpGlobal?themaGlobal=help_est_ufa_10_2025">ELSTER · Anlage V guidance ↗</a>`)}${sectionCard('02 · Progressive income tax','2026 law, applied to full euros',`<p>§32a uses the €12,348 basic allowance, progressive formula zones, then 42% from €69,879 and 45% from €277,826 for single taxable income. Joint assessment uses twice the tax on half the shared taxable income.</p><p>Marginal rates describe the next euro; effective tax is a different measure. Property order changes attribution, never the combined liability.</p><a class="source-link" target="_blank" rel="noreferrer" href="https://www.gesetze-im-internet.de/estg/__32a.html">EStG §32a · tariff and splitting ↗</a>`)}${sectionCard('03 · AfA and costs','',`<p>Standard linear AfA is 2.5% for buildings completed before 1925, 2% for 1925–2022, and 3% from 2023. Custom useful-life rates require evidence. Only the building basis is depreciated; the acquisition year is month-prorated.</p><p>The model supports one straight-line basis and no depreciation before the entered start date. Use it from acquisition; already depreciated assets, special/degressive AfA or later capital additions need a reviewed override. First-three-year repairs may require capitalization under the 15% rule. No automatic legal classification is attempted.</p><a class="source-link" target="_blank" rel="noreferrer" href="https://www.gesetze-im-internet.de/estg/__7.html">EStG §7 · depreciation ↗</a><a class="source-link" target="_blank" rel="noreferrer" href="https://www.gesetze-im-internet.de/estg/__6.html">EStG §6 · acquisition-related costs ↗</a>`)}${sectionCard('04 · Pension treatment','2027 new depot mechanism',`<p>Certified new depot: support on up to €1,800 own contributions per eligible person; 50% on the first €360 and 25% on the next €1,440. Child support is up to €300 per allocated child. Contributions plus allowances enter the favorable check. Allowances are added back where the deduction wins, so benefits are not counted twice.</p><p>New depot support is disabled for 2026. Direct eligibility only. Rürup is capped at €30,826 per person in the frozen model, taking employer and employee statutory pension contributions into account. Ordinary Schicht 3 contributions reduce cash, not current taxable income.</p><a class="source-link" target="_blank" rel="noreferrer" href="https://www.bundesfinanzministerium.de/Content/DE/FAQ/reform-der-privaten-altersvorsorge.html">BMF · final reform FAQ ↗</a><a class="source-link" target="_blank" rel="noreferrer" href="https://recht.bund.de/bgbl/1/2026/156/VO.html">2026 Altersvorsorgereformgesetz ↗</a>`)}${sectionCard('05 · Household assumptions','',`<p>Employee allowances: €1,230 per earner (limited to salary), €36 special-expense allowance per assessed person unless other entered special deductions are larger. Social cash estimates include employee RV, AV, GKV and care; tax deductions use employee RV, 96% of GKV, and care. Other capped insurance deductions are not added automatically.</p><p>2026 caps: RV/AV €101,400 and health/care €69,750. Kindergeld is €259 monthly per child, with a €9,756 allowance favorable check. Full-year children / full allowance are assumed; non-joint parents should use an adviser’s calculation. Solidarity: €20,350/€40,700 threshold and mitigation zone; child allowances are considered for its basis.</p><p>Church tax is a simple approximate surcharge. Its own deductibility, church caps, single-parent relief, mixed custody, midijobs, pensioners and private health need professional review. The progression input uses the supplied net adjusted amount and a simplified average-rate method; it does not determine that legal amount.</p><a class="source-link" target="_blank" rel="noreferrer" href="https://www.bmas.bund.de/DE/Service/Gesetze-und-Gesetzesvorhaben/sozialversicherungs-rechengroessenverordnung-2026.html">BMAS · 2026 contribution caps ↗</a><a class="source-link" target="_blank" rel="noreferrer" href="https://www.gesetze-im-internet.de/solzg_1995/BJNR097500993.html">Solidarity surcharge law ↗</a>`)}${sectionCard('06 · What you can share','',`<p>Print the tax worksheet or export the annual CSV as a review attachment. Values should be reconciled with your bank certificates and actual expense records. No data is submitted to ELSTER or Finanzamt by this app.</p><p>Tax class affects withholding; it does not lower final annual income tax. Tax refund = entered tax paid − estimated liability. The official BMF payroll algorithm is not implemented. Eligible rental losses can support a Lohnsteuerermäßigung request; approval is separate.</p><a class="source-link" target="_blank" rel="noreferrer" href="https://www.finanzamt-muenchen.de/steuerinfos/haeufig-gestellte-fragen/lohnsteuerabzug-und-lohnsteuerermaessigung">Finanzamt · withholding and final tax ↗</a>`)}${sectionCard('07 · Your scenario & data','',`<p>Your entries stay in this browser’s local storage. There is no cloud sync. Export a JSON backup before changing browsers, devices or clearing site data. Imports are validated before replacing your current scenario.</p><div class="actions">${button('Save JSON','export-json')}${button('Load JSON','import-json')}</div><p>Scenario base year: <strong>${state.baseYear}</strong>. Projections cover ${state.baseYear}–${state.baseYear+9}.</p><form id="settings-form"><div class="form-grid two">${field('baseYear','Scenario base year',state.baseYear,'number','Loan / rental start dates remain unchanged.',{min:2026,max:2100,step:1})}<div class="field"><label>&nbsp;</label><button class="btn primary" type="submit">Update horizon</button></div></div></form>`)}${sectionCard('08 · Model limitations','Reviewed 06 November 2026',`<p>Residential private letting and resident employee household planning. No foreign tax, VAT, corporate property, §35a credits, §21 reduced-rent deductibility test, separate spouse-return allocation, restricted loss-offset rules or loss carryovers. Loans assume full initial disbursement, regular monthly interest and payments from the entered start, with extra repayments in December. Exact bank day-count conventions are not implemented.</p><p>Inputs and dates must be reconciled. Property capital expenditure is cash-only until you update the confirmed AfA basis. Salary growth and cost/rent steps are scenarios. Future law, tax bands, social caps and property values are unknown and not forecast here.</p><p><strong>No exact filing or refund guarantee.</strong> The calculation is transparent and testable, but cannot replace document verification or a tax assessment.</p>`)}</div>`;}
function uiKit(){return {header,button,icon,esc,euro,notice,stat,field,check,sectionCard};}
function activeStatus(a){const off=state.properties.length-a.stages.length;const pending=a.stages.filter(x=>['rent','buildingShare','dates','loans','costs','growth'].some(k=>state.properties.find(p=>p.id===x.id).confirmations?.[k]!==true)).length;return `<div class="active-status no-print"><span><strong>${a.stages.length}</strong> active properties · ${off} disabled · ${pending} need input confirmation</span><div>${button('Enable / disable','show-scenarios','small')}${button('Risk & comparison','show-risk','small')}</div></div>`;}
function render(){const a=analyze(state,year),rows=Array.from({length:10},(_,i)=>analyze(state,state.baseYear+i));const active=view==='property'?'properties':view;const nav=[['overview','grid','Overview'],['scenarios','leaf','Scenario switches'],['risk','chart','Risk & decisions'],['properties','building','Properties'],['projection','chart','10-year outlook'],['payroll','check','Payslip reconciliation'],['tax','tax','Household tax'],['report','file','Tax worksheet'],['sync','file','Data sync'],['methodology','book','Rules & assumptions']];$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-icon">${icon('home')}</span>immoledger<span style="color:#c9e19a">.</span></div><div class="brand-sub">Property. Perspective.</div><div class="nav-label">WORKSPACE</div><nav class="nav" aria-label="Main navigation">${nav.map(([v,i,l])=>`<button class="${active===v?'active':''}" data-action="nav" data-view="${v}" ${active===v?'aria-current="page"':''}>${icon(i)}${l}${v==='properties'?`<span class="count">${state.properties.length}</span>`:''}</button>`).join('')}</nav><div class="property-items"><div class="nav-label">YOUR PROPERTIES</div><nav class="nav">${state.properties.filter(propertyOn).map((p,i)=>`<button data-action="open-property" data-id="${esc(p.id)}"><span class="dot ${i%2?'blue':''}"></span><span class="property-nav">${esc(p.name)}</span></button>`).join('')}<button data-action="add-property">${icon('plus')}Add property</button></nav></div><div class="sidebar-bottom"><span class="avatar" aria-hidden="true">IL</span><div style="font-size:12px;color:#e6eddf;padding-top:2px">Personal workspace</div><small style="font-size:10px">German rental investments</small></div></aside><main class="main"><div class="topbar"><div class="breadcrumb">Workspace &nbsp; / &nbsp; <strong>${esc(nav.find(n=>n[0]===active)?.[2]||'Properties')}</strong></div><div class="top-tools">${button('Sync data','sync-open','small')}<span class="sync-indicator" data-sync-status>${esc(syncUI.status)}</span>${button('Save JSON','export-json','small')}${button('Load JSON','import-json','small')}<span class="saved-status ${dirty?'unsaved':''}"><span class="local-dot"></span>${persistence.persisted?'Saved in this browser':persistence.error?'Not saved · export backup':'Illustrative demo'}</span><span class="pill">DE · 2026 tax model</span><label for="year-select" class="sr-label">Year</label><select id="year-select" class="year-select" aria-label="Calculation year">${rows.map(r=>`<option ${r.year===year?'selected':''}>${r.year}</option>`).join('')}</select></div></div><div class="content">${state.demo===true?notice('Illustrative demo: all starter properties, salary, payroll and budget amounts are fictional. Enter your verified data or load a JSON backup.'):''}${periodToolbar(a)}${activeStatus(a)}${loadError?notice(esc(loadError),true):''}${view==='sync'?syncUI.markup():view==='scenarios'?renderStrategies(state,uiKit()):view==='risk'?renderRisk(state,uiKit()):view==='overview'?dashboard(a,rows):view==='properties'?properties(a):view==='property'?propertyEditor():view==='projection'?projection(rows):view==='payroll'?payrollView(a):view==='tax'?taxView(a):view==='report'?report(a):methodology()}<footer class="footer"><span>ImmoLedger · A little more clarity for every investment.</span><span>Planning estimates · Rules reviewed 06 Nov 2026</span></footer></div></main></div><input id="import-file" type="file" accept="application/json,.json">`;}
function applyForm(){if(!dirty)return true;const form=$('#profile-form')||$('#household-form')||$('#payroll-form')||$('#risk-form');if(!form)return true;if(!form.reportValidity())return false;const draft=structuredClone(state),target=form.id==='profile-form'?draft.properties.find(p=>p.id===selected):form.id==='payroll-form'?draft.payroll:form.id==='risk-form'?draft.risk:draft.household;for(const el of form.elements){if(!el.name)continue;const parts=el.name.split('.');let obj=target;for(let i=0;i<parts.length-1;i++){if(obj[parts[i]]==null)obj[parts[i]]={};obj=obj[parts[i]];}obj[parts.at(-1)]=el.type==='checkbox'?el.checked:el.type==='number'?(el.value===''?null:Number(el.value)):el.value;if(el.tagName==='SELECT'&&el.name==='churchRate')obj[parts.at(-1)]=Number(el.value);}
 if(form.id==='profile-form'){const p=target;for(const [y,a]of Object.entries(p.actuals))if(Object.values(a).every(v=>v==null||v===''))delete p.actuals[y];}else if(form.id==='household-form'){if(target.childrenUnder25>target.children){toast('Children under 25 cannot exceed eligible children here. Use parent status for adult children.');return false;}if(target.depotChildren+target.spouseDepotChildren>target.children){toast('Allocate no more depot child allowances than your eligible child count.');return false;}}
 try{validateState(draft);state=draft;save();return true;}catch(e){toast(e.message);return false;}}
function download(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function csv(rows){return '\uFEFF'+rows.map(row=>row.map(v=>{let s=String(v??'');if(typeof v!=='number'&&/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}).join(';')).join('\r\n');}
function exportReport(){const a=analyze(state,year),rows=[['ImmoLedger review worksheet',year,'EUR','Not an official Anlage V'],['Property','Basis','Receipts','Interest','Deductible costs','AfA','Taxable result','Principal','All cash costs','Cash before tax','Cash needed before tax relief','Attributed tax benefit','Cash needed after tax relief','Evidence / assumptions']];for(const p of a.stages){const source=state.properties.find(v=>v.id===p.id);rows.push([p.name,p.actual?'Actual overrides':'Forecast',p.income,p.interest,p.deductibleCosts,p.afa,p.result,p.principal,p.costs,p.cash,cashNeeded(p.cash),p.saving,cashNeeded(p.afterTaxCash),source.afaEvidence+' '+p.note]);}rows.push(['TOTAL','',...['income','interest','deductibleCosts','afa','result','principal','costs','cash'].map(k=>a.stages.reduce((s,p)=>s+p[k],0)),cashNeeded(a.cash),a.totalBenefit,cashNeeded(a.afterTaxCash)]);rows.push([],['Tax model','2026 parameters frozen'],['Household taxable income',a.final.taxable],['Estimated final tax',a.final.tax],['Property tax reduction',a.totalBenefit],['Final marginal rate (%)',a.final.marginal],['Estimated refund (+) / due (-)',a.final.refund]);download(`immoledger-tax-worksheet-${year}.csv`,csv(rows),'text/csv;charset=utf-8');}
function exportProjection(){const rows=Array.from({length:10},(_,i)=>analyze(state,state.baseYear+i)),u=period==='monthly'?'EUR/month average':'EUR/year',v=n=>periodAmount(n,period);download(`immoledger-10-year-${period}.csv`,csv([['Year',`Rental receipts (${u})`,`Taxable rental result (${u})`,`Property tax benefit (${u})`,`Cash before tax (${u})`,`Cash needed before tax relief (${u})`,`Cash after tax (${u})`,`Principal repaid (${u})`,'Year-end debt (EUR)',`Household tax (${u})`,`Household available (${u})`,'Marginal income-tax rate (%)'],...rows.map(r=>[r.year,v(r.stages.reduce((s,p)=>s+p.income,0)),v(r.totalResult),v(r.totalBenefit),v(r.cash),v(cashNeeded(r.cash)),v(r.afterTaxCash),v(r.principal),r.balance,v(r.final.tax),v(r.householdAvailable),r.final.marginal])]),'text/csv;charset=utf-8');}
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='settings-form'){const value=Number(new FormData(e.target).get('baseYear'));if(value<2026||value>2100||!Number.isInteger(value))return;state.baseYear=value;year=value;save();render();toast('Projection horizon updated.');return;}if(applyForm()){render();toast(persistence.persisted?'Saved. All calculations updated.':'Calculated, but not saved. Export a JSON backup.');}});
document.addEventListener('input',e=>{if(e.target.closest('form')){dirty=true;const status=$('.saved-status');if(status){status.textContent='Unsaved changes';status.classList.add('unsaved');}}});
document.addEventListener('change',async e=>{if(e.target.id==='year-select'){if(!applyForm()){e.target.value=year;return;}year=Number(e.target.value);render();}if(e.target.id==='import-file'){const file=e.target.files[0];if(!file)return;try{if(file.size>MAX_BACKUP_BYTES)throw new Error('Backup must be smaller than 2 MB.');const candidate=deserializeScenario(await file.text());if(!confirm('Replace this browser’s scenario with this backup? Export a backup first if you want to keep the current scenario.'))return;state=candidate;year=state.baseYear;selected=null;view='overview';loadError='';save();render();toast('Scenario restored.');}catch(error){toast('Import rejected: '+error.message);e.target.value='';}}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;if(action.startsWith('sync-')&&action!=='sync-open'){try{if(action==='sync-connect'){const input=$('#sync-token'),token=input?.value||'';if(input)input.value='';await syncUI.connect(token);}else if(action==='sync-load')await syncUI.load();else if(action==='sync-publish')await syncUI.publish();else if(action==='sync-disconnect')syncUI.disconnect();else if(action==='sync-backup')download('immoledger-previous-browser.json',syncUI.previous(),'application/json');}catch(error){toast(error.message);}return;}if(!['import-json','export-json','print'].includes(action)&&!applyForm())return;
 const p=state.properties.find(p=>p.id===selected);let scroll=true;switch(action){case 'sync-open':view='sync';break;case 'show-scenarios':view='scenarios';break;case 'show-risk':view='risk';break;case 'toggle-property':{const item=state.properties.find(p=>p.id===b.dataset.id);item.enabled=!propertyOn(item);save();scroll=false;break;}case 'toggle-strategy':if(!state.strategies)state.strategies={};state.strategies[b.dataset.key]=!strategyOn(state,b.dataset.key);save();scroll=false;break;case 'toggle-guarantee':{const item=state.properties.find(p=>p.id===b.dataset.id);item.guaranteePlan.enabled=!item.guaranteePlan.enabled;save();scroll=false;break;}case 'open-guarantee':selected=b.dataset.id;view='property';section='guarantee';break;case 'toggle-cost':p.costs[Number(b.dataset.index)].enabled=p.costs[Number(b.dataset.index)].enabled===false;save();scroll=false;break;case 'stress-preset':Object.assign(state.risk,{vacancyStressPercent:20,salaryStressPercent:20,repairStress:5000,rateShockPoints:2});save();scroll=false;break;case 'prepare-ai':case 'copy-ai':case 'download-ai':{const prompt=buildHandoff(state);const area=$('#ai-report');if(area)area.value=prompt;if(action==='download-ai'){download('immoledger-active-scenario-analysis.txt',prompt,'text/plain;charset=utf-8');return;}if(action==='copy-ai'){try{await navigator.clipboard.writeText(prompt);toast('Fresh enabled-scenario report copied. Paste it into ChatGPT.');}catch{area?.focus();area?.select();toast('Select and copy the prepared text, then paste it into ChatGPT.');}}else{area?.scrollIntoView({behavior:'smooth',block:'center'});toast('Fresh report prepared from enabled items only.');}return;}case 'set-period':period=b.dataset.period;try{localStorage.setItem('immoledger.view.v1',JSON.stringify({period}));}catch{}scroll=false;break;case 'show-tax':view='tax';break;case 'show-payroll':view='payroll';break;case 'toggle-series':{const key=b.dataset.series;const other=key==='benefit'?'cash':'benefit';if(visibleSeries[key]&&!visibleSeries[other]){toast('Keep at least one chart series visible.');return;}visibleSeries[key]=!visibleSeries[key];scroll=false;break;}case 'chart-select-year':year=Number(b.dataset.chartYear);scroll=false;break;case 'nav':view=b.dataset.view;break;case 'properties':case 'report':case 'overview':view=action;break;case 'open-property':selected=b.dataset.id;view='property';section='details';break;case 'section':section=b.dataset.section;scroll=false;break;case 'add-property':{const fresh=newProperty();fresh.start=state.baseYear+'-01';state.properties.push(fresh);selected=fresh.id;view='property';section='details';save();break;}case 'duplicate':{const copy=structuredClone(state.properties.find(p=>p.id===b.dataset.id));copy.id=uid();copy.name+=' · copy';copy.enabled=false;copy.loans.forEach(l=>l.id=uid());copy.costs.forEach(c=>c.id=uid());state.properties.push(copy);save();toast('Profile duplicated and disabled until you enable it.');break;}case 'delete-property':{const i=state.properties.findIndex(p=>p.id===b.dataset.id);deleted={index:i,property:state.properties.splice(i,1)[0]};save();toast('Property removed. Undo is available below the list.');break;}case 'undo-delete':if(deleted){state.properties.splice(deleted.index,0,deleted.property);deleted=null;save();}break;case 'add-loan':p.loans.push({id:uid(),name:'New loan',amount:0,interest:4.5,repayment:1.5,start:p.start,fixedYears:10,extra:0});save();scroll=false;break;case 'remove-loan':p.loans.splice(Number(b.dataset.index),1);save();scroll=false;break;case 'add-cost':p.costs.push({id:uid(),name:'New cost',amount:0,frequency:'monthly',from:p.start,to:'',type:'deductible',growth:0});save();scroll=false;break;case 'remove-cost':p.costs.splice(Number(b.dataset.index),1);save();scroll=false;break;case 'clear-actuals':delete p.actuals[year];save();scroll=false;break;case 'move-up':case 'move-down':{const i=state.properties.findIndex(p=>p.id===b.dataset.id),j=i+(action==='move-up'?-1:1);if(j>=0&&j<state.properties.length){[state.properties[i],state.properties[j]]=[state.properties[j],state.properties[i]];save();}scroll=false;break;}case 'select-year':year=Number(b.dataset.year);view='overview';break;case 'export-json':if(!applyForm())return;download(`immoledger-scenario-${new Date().toISOString().slice(0,10)}.json`,serializeScenario(state),'application/json');toast('JSON backup exported.');return;case 'import-json':$('#import-file').click();return;case 'export-report':exportReport();return;case 'export-projection':exportProjection();return;case 'print':window.print();return;default:return;}
 render();if(scroll)window.scrollTo({top:0,behavior:'instant'});
});
function inspectYear(target){const point=target.closest('[data-chart-year]');if(!point)return;const wrap=point.closest('.chart-wrap');const row=chartRows.find(r=>r.year===Number(point.dataset.chartYear));if(!wrap||!row)return;wrap.querySelectorAll('.chart-year').forEach(p=>p.classList.toggle('is-inspected',p.dataset.chartYear===point.dataset.chartYear));wrap.querySelector('.chart-detail').innerHTML=chartDetail(row,period);}
document.addEventListener('pointerover',e=>inspectYear(e.target));
document.addEventListener('focusin',e=>inspectYear(e.target));
document.addEventListener('keydown',e=>{const point=e.target.closest('.chart-hit');if(!point)return;if(e.key==='Enter'||e.key===' '){e.preventDefault();point.dispatchEvent(new MouseEvent('click',{bubbles:true}));}else if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();const nodes=[...point.closest('svg').querySelectorAll('.chart-hit')];const i=nodes.indexOf(point);nodes[Math.max(0,Math.min(nodes.length-1,i+(e.key==='ArrowRight'?1:-1)))].focus();}});
window.addEventListener('beforeunload',e=>{if(dirty||syncUI.pending){e.preventDefault();e.returnValue='';}});
const syncUI=createSyncUI({getState:()=>state,replaceState:next=>{state=next;year=state.baseYear;selected=null;loadError='';const ok=persistence.save(state);dirty=!ok;render();if(!ok)toast('Repository data loaded in memory. Browser storage unavailable; export JSON to keep a local copy.');},hasUnsaved:()=>dirty,beforeSync:()=>applyForm(),storage:localStorage,confirm:message=>confirm(message),toast,onChange:()=>{if(view==='sync')render();else{const indicator=$('[data-sync-status]');if(indicator)indicator.textContent=syncUI.status;}}});
render();
